def comps(a,v):
 seen=set();out=[]
 for r in range(4):
  for c in range(4):
   if a[r][c]==v and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));co=[]
    while q:
     y,x=q.pop();co.append((y,x))
     for dy,dx in ((0,1),(0,-1),(1,0),(-1,0)):
      z=y+dy,x+dx
